import{_ as o,o as a,c as t,a3 as c}from"./chunks/framework.B8xISX-C.js";const u=JSON.parse('{"title":"Limits","description":"","frontmatter":{},"headers":[],"relativePath":"reference/limits.md","filePath":"reference/limits.md"}'),d={name:"reference/limits.md"};function s(i,e,r,l,n,h){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h1><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><ul><li>Text shown in the game uses printable Latin-1 (the bitmap fonts have no other glyphs): mod titles, author names and every text string.</li><li>Catalog strings (keys, text keys) are printable ASCII.</li><li>Numbers are integers; fractions are <code>{ num, den }</code> records.</li><li>At most four applications per research field (the research screen shows four choices).</li><li>Field levels are 0 to 22 and AI groups 0 to 41 (the research value tables).</li><li>The custom race screen shows 22 special picks a page; with more, its third column pages.</li><li>New hulls, governments, drives and fuel cells are not possible: those catalogs are closed (their records are patchable). Their behaviour is tied to the hull sizes, the government family and the movement tables.</li><li>Mods never write numeric ids: records get ids from the mod&#39;s own id block, and references between records use keys.</li><li>Record keys are <code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: the namespace is the package id with <code>-</code> read as <code>_</code> (<code>yourname.my-mod</code> -&gt; <code>yourname.my_mod.prism_lance</code>).</li></ul><h2 id="text-art-and-audio" tabindex="-1">Text, art and audio <a class="header-anchor" href="#text-art-and-audio" aria-label="Permalink to &quot;Text, art and audio&quot;">​</a></h2><ul><li>Text: <code>i18n/en/&lt;file&gt;.json</code> maps keys to ICU messages; other locales are reported and not used yet. A new key holds the package namespace as dotted segments (<code>ui.yourname.my_mod.hello</code>).</li><li>A mod may override base text, except proper names (<code>race.*</code>, <code>names.*</code>, <code>tech.field.*.name</code>, <code>tech.app.*.name</code>, <code>ldr.*.name</code>). An override uses only the base message&#39;s arguments, with the same kind; a new key takes none, except the ruler name pools (<code>names.rulers.*</code>: <code>i</code>, <code>sex</code>).</li><li>Messages: printable Latin-1 without the soft hyphen, no tags, dates or times, an <code>other</code> arm in every plural and select, at most 2000 characters, nesting 4 and 32 arms; at most 4000 messages per package.</li><li>Art and audio: <code>assets/roles.json</code> (<code>&quot;$schema&quot;: &quot;carina-roles/1&quot;</code>) with <code>roles</code> (<code>{ &quot;role&quot;, &quot;file&quot;, &quot;frames&quot;? }</code>), <code>races</code> (<code>{ &quot;race&quot;, &quot;artBase&quot; }</code>) and <code>artFrom</code> (<code>{ &quot;catalog&quot;: &quot;buildings&quot;, &quot;key&quot;, &quot;from&quot; }</code>: a new building drawn as a base one).</li><li>A role is a base role (an override), a picture of a race the package adds, or a new role named <code>&lt;namespace&gt;.&lt;name&gt;</code>. Images have the base role&#39;s kind and exact size; picture atlases too.</li><li>A combat ship atlas (<code>ships.combat.*</code>, <code>shipsai.combat.*</code>) brings its frames: <code>&lt;key&gt;.h&lt;0-4&gt;.f&lt;0-3&gt;.x&lt;X&gt;.y&lt;Y&gt;</code>, every unit key and heading at frame 0, each rect inside the image.</li><li>A building you add can have its own colony lot picture: the atlas role <code>colony.lot.&lt;building key with _ replaced by -&gt;</code> (for <code>acme.tools.big_lab</code>: <code>colony.lot.acme.tools.big-lab</code>), listed with 36 frames, one per cell of the 6 x 6 lot, named <code>r&lt;0-5&gt;c&lt;0-5&gt;_x&lt;X&gt;_y&lt;Y&gt;</code> (X, Y: the screen position of the sprite&#39;s top-left pixel, as the base lot atlases do). Each sprite stands on its cell: its screen rect lies inside the cell&#39;s box (the cell&#39;s four grid corners, 2 px margin, room above for a building 1.15 cell widths high), frames do not overlap in the image, and the cell boxes are listed in <code>src/content/presentation/building-art.ts</code>. A building drawn as a base one (<code>artFrom</code>) must not also list its own lot role (<code>art-from-twice</code>). A building with neither picture is not drawn on the lot.</li><li>Audio: <code>music.cue.&lt;id&gt;</code> and <code>sfx.&lt;nnn&gt;</code> as Ogg (Opus or Vorbis), with an optional <code>&lt;role&gt;.m4a</code> twin. Music at most 300 s, effects at most 10 s, by the file&#39;s own length.</li><li>Packages stack in load order: a later package&#39;s role or text replaces an earlier one&#39;s. Text and art are not part of the rules hash.</li></ul><h2 id="catalogs" tabindex="-1">Catalogs <a class="header-anchor" href="#catalogs" aria-label="Permalink to &quot;Catalogs&quot;">​</a></h2><ul><li>Open to new records: <a href="./applications"><code>applications</code></a>, <a href="./armor"><code>armor</code></a>, <a href="./buildings"><code>buildings</code></a>, <a href="./computers"><code>computers</code></a>, <a href="./race-picks"><code>race-picks</code></a>, <a href="./races"><code>races</code></a>, <a href="./shields"><code>shields</code></a>, <a href="./specials"><code>specials</code></a>, <a href="./tech-fields"><code>tech-fields</code></a>, <a href="./weapons"><code>weapons</code></a>.</li><li>Closed (patch only): <code>ai-objectives</code>, <code>ai-personality</code>, <code>ai-tuning</code>, <code>assimilation-rules</code>, <code>audience-rules</code>, <code>build-lists</code>, <code>cheat-codes</code>, <code>colonize-rules</code>, <code>colony-economy</code>, <code>combat-rules</code>, <code>council-rules</code>, <code>difficulty</code>, <code>diplomacy-rules</code>, <code>drives</code>, <code>espionage-rules</code>, <code>event-rules</code>, <code>events</code>, <code>finance-rules</code>, <code>fuel-cells</code>, <code>galaxy-gen</code>, <code>governments</code>, <code>governor-policies</code>, <code>history-rules</code>, <code>hulls</code>, <code>leader-rules</code>, <code>leaders</code>, <code>message-rules</code>, <code>monster-rules</code>, <code>monsters</code>, <code>movement</code>, <code>planet-mod-rules</code>, <code>planet-types</code>, <code>population-rules</code>, <code>production-rules</code>, <code>race-rules</code>, <code>relations-matrix</code>, <code>research</code>, <code>score</code>, <code>settings</code>, <code>ship-design</code>, <code>ship-lifecycle</code>, <code>star-types</code>, <code>start-state</code>, <code>transport-rules</code>, <code>troop-units</code>, <code>vaelori-designs</code>, <code>vaelori-rules</code>, <code>weapon-mods</code>.</li><li>Ids: base records stay below 1024; each mod that adds records gets one block of 256 ids per catalog (at most 60 blocks in a game), so at most 256 new records per catalog per mod.</li></ul><h2 id="package" tabindex="-1">Package <a class="header-anchor" href="#package" aria-label="Permalink to &quot;Package&quot;">​</a></h2><ul><li>Zip at most 32 MiB, 2000 entries, 128 MiB unpacked; rules files (records, patches, migrations) at most 4 MiB in all.</li><li>One JSON file at most 2 MiB, nested at most 32 deep, 200000 values; <code>mod.json</code> at most 64 KiB.</li><li>Paths: ASCII letters, digits, <code>.</code>, <code>_</code>, <code>-</code>; at most 200 bytes and 8 segments; no two paths that differ only by case.</li><li>Images: PNG or WebP, at most 4096 pixels a side, 16 Mpx each and 64 Mpx in all (1 Mpx = 1048576 pixels). Audio: Ogg (and m4a).</li><li>Folders for later formats are refused with <code>needs-newer-game</code>: <code>rules/</code>, <code>scenarios/</code>, <code>campaigns/</code>, <code>ui/</code>, <code>scripts/</code>.</li><li>No JavaScript, HTML or other code: a package is data only.</li></ul>',9)])])}const p=o(d,[["render",s]]);export{u as __pageData,p as default};
